window.QBANK={"1":[{"i":"REGOX-reg_entities-001","t":"Under IRC §274(n)(1), the amount allowable as a deduction for food or beverage expenses generally may not exceed 50 percent of the amount that would otherwise be deductible.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §274(n)(1)","rat":"A deduction for food and beverage costs is generally limited to 50%."},{"i":"REGOX-reg_entities-002","t":"Under IRC §274(n), the 50 percent limitation on food or beverage expenses also applies to lodging expenses incurred on the same business trip.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §274(n)(1)","rat":"The 50% limit applies only to food and beverage costs, not to lodging."},{"i":"REGOX-reg_entities-003","t":"Under IRC §274(a)(1), no deduction is allowed for entertainment, amusement, or recreation expenses even if the activity is related to the taxpayer's trade or business.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §274(a)(1)","rat":"Entertainment, amusement, and recreation expenses are generally nondeductible regardless of business connection."},{"i":"REGOX-reg_entities-004","t":"Under IRC §103(a), interest received on a State or local bond is included in gross income for federal income tax purposes.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §103(a)","rat":"Interest on state and local bonds is tax-exempt interest excluded from gross income."},{"i":"REGOX-reg_entities-005","t":"Under IRC §103(b)(1), interest on a private activity bond that is not a 'qualified bond' within the meaning of section 141 is excluded from gross income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §103(b)(1)","rat":"Interest on a private activity bond that is not a qualified bond is an exception to the exemption and is included in gross income."},{"i":"REGOX-reg_entities-006","t":"Under IRC §168(c), the applicable MACRS recovery period for nonresidential real property is 39 years.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(c)","rat":"Nonresidential real property has a 39-year recovery period."},{"i":"REGOX-reg_entities-007","t":"Under IRC §168(b)(3)(A), nonresidential real property must be depreciated using the straight line method.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(b)(3)(A)","rat":"Nonresidential real property is depreciated under the straight line method."},{"i":"REGOX-reg_entities-008","t":"Under IRC §168(d)(1), the applicable convention for most tangible personal property, except as otherwise provided, is the mid-quarter convention.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §168(d)(1)","rat":"The general convention is the half-year convention, not the mid-quarter convention."},{"i":"REGMC-reg_entities-001","t":"Under IRC §274, which of the following is fully disallowed as a deduction under subsection (a), rather than merely limited to 50 percent under subsection (n)?","c":"A","mc":{"s":"Under IRC §274, which of the following is fully disallowed as a deduction under subsection (a), rather than merely limited to 50 percent under subsection (n)?","d":"","o":["Business meals with a client where business is discussed","Dues paid for membership in a club organized for business, pleasure, recreation, or other social purpose","Food furnished to employees on the business premises of the taxpayer","Meals provided during business travel away from home"],"a":2,"cite":"26 U.S.C. §274(a)(3)","rat":"Club dues are fully nondeductible under §274(a)(3)."}},{"i":"REGMC-reg_entities-002","t":"Under IRC §103, interest on which of the following bonds is NOT excluded from gross income?","c":"A","mc":{"s":"Under IRC §103, interest on which of the following bonds is NOT excluded from gross income?","d":"","o":["An obligation of a State","An obligation of a political subdivision of a State","An arbitrage bond within the meaning of section 148","A bond meeting the requirements of section 149"],"a":3,"cite":"26 U.S.C. §103(b)(2)","rat":"An arbitrage bond is taxable under the §103(b)(2) exception."}},{"i":"REGMC-reg_entities-003","t":"Under IRC §168(c), what is the applicable MACRS recovery period for residential rental property?","c":"A","mc":{"s":"Under IRC §168(c), what is the applicable MACRS recovery period for residential rental property?","d":"","o":["20 years","25 years","27.5 years","39 years"],"a":3,"cite":"26 U.S.C. §168(c)","rat":"Residential rental property has a 27.5-year recovery period."}}],"2":[{"i":"REGOX-reg_entities-009","t":"Under IRC §11(b), the tax imposed on the taxable income of a C corporation is 21 percent.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §11(b)","rat":"The corporate tax rate is a flat 21%."},{"i":"REGOX-reg_entities-010","t":"Under IRC §63(a), taxable income means gross income minus the deductions allowed by chapter 1, other than the standard deduction.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §63(a)","rat":"The general rule of §63(a): taxable income = gross income - deductions (other than the standard deduction)."},{"i":"REGOX-reg_entities-011","t":"Under IRC §63(a), a C corporation computes taxable income as gross income minus the deductions allowed by chapter 1, other than the deduction for personal exemptions.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §63(a)","rat":"The item excluded under (a) is the standard deduction, not personal exemptions."},{"i":"REGOX-reg_entities-012","t":"Under IRC §162(a)(1), a reasonable allowance for salaries or other compensation for personal services actually rendered is deductible as an ordinary and necessary business expense.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §162(a)(1)","rat":"Reasonable salary is deductible as an ordinary and necessary business expense."},{"i":"REGOX-reg_entities-013","t":"Under IRC §162(b), a taxpayer may deduct a charitable contribution under section 162(a) without regard to the percentage limitations of section 170.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §162(b)","rat":"A charitable contribution that fails the §170 requirements is not deductible under §162(a) either."},{"i":"REGOX-reg_entities-014","t":"Under IRC §243(a)(1), a corporation is generally allowed a deduction equal to 50 percent of dividends received from a taxable domestic corporation.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §243(a)(1)","rat":"The general dividends-received deduction (DRD) rate is 50%."},{"i":"REGOX-reg_entities-015","t":"Under IRC §243(c)(1), the dividends-received deduction percentage is increased to 65 percent for dividends received from a 20-percent owned corporation.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §243(c)(1)","rat":"Dividends from a corporation owned 20% or more qualify for a 65% DRD rate."},{"i":"REGOX-reg_entities-016","t":"Under IRC §243(a)(3), a qualifying dividend received from a member of the same affiliated group is eligible only for the 50 percent dividends-received deduction.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §243(a)(3)","rat":"Qualifying dividends within the same affiliated group qualify for a 100% deduction."},{"i":"REGOX-reg_entities-018","t":"Under IRC §172(b)(1)(A)(ii)(II), a net operating loss arising in a taxable year beginning after December 31, 2017, is carried forward to each succeeding taxable year, with no expiration.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §172(b)(1)(A)(ii)(II)","rat":"NOLs arising after 2017 may be carried forward indefinitely."},{"i":"REGOX-reg_entities-019","t":"Under IRC §172(b)(1)(A), a net operating loss arising in a taxable year beginning after December 31, 2017 (other than a farming loss or certain insurance company loss) may be carried back 2 taxable years before being carried forward.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §172(b)(1)(A)","rat":"NOLs arising after 2017 generally cannot be carried back; only carryforward is allowed."},{"i":"REGOX-reg_entities-020","t":"Under IRC §172(a)(2)(B), the NOL deduction attributable to losses arising after 2017 is limited to 80 percent of taxable income computed without regard to the NOL deduction and the deductions under sections 199A and 250.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §172(a)(2)(B)","rat":"NOLs arising after 2017 are limited to 80% of taxable income."},{"i":"REGOX-reg_entities-021","t":"Under IRC §172(b)(1)(B)(i), a farming loss may be carried back to each of the 2 taxable years preceding the taxable year of the loss.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §172(b)(1)(B)(i)","rat":"A farming loss may be carried back 2 years."},{"i":"REGOX-reg_entities-022","t":"Under IRC §1211(a), a corporation may deduct capital losses only to the extent of its capital gains for the taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1211(a)","rat":"A corporation's capital losses are deductible only against capital gains."},{"i":"REGOX-reg_entities-023","t":"Under IRC §1211(a), a corporation, like an individual under section 1211(b), may deduct up to $3,000 of capital losses in excess of capital gains against ordinary income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1211(a)","rat":"The $3,000 offset rule of §1211(b) does not apply to corporations."},{"i":"REGOX-reg_entities-024","t":"Under IRC §172(c), a net operating loss is defined as the excess of the deductions allowed by chapter 1 over gross income, computed with the modifications specified in subsection (d).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §172(c)","rat":"An NOL is defined as the amount by which deductions exceed gross income."},{"i":"REGOX-reg_entities-025","t":"Under IRC §38(a), the general business credit for the taxable year equals the sum of business credit carryforwards, the current year business credit, and business credit carrybacks.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §38(a)","rat":"The general business credit is the sum of carryforward, current-year, and carryback amounts."},{"i":"REGOX-reg_entities-026","t":"Under IRC §38(b)(4), the research credit determined under section 41(a) is included as part of the current year business credit.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §38(b)(4)","rat":"The research credit under §41 is one of the current-year business credit components."},{"i":"REGOX-reg_entities-027","t":"Under IRC §38(c)(1), the general business credit is limited to the excess of net income tax over the greater of the tentative minimum tax or 25 percent of net regular tax liability exceeding $25,000.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §38(c)(1)","rat":"The general business credit is limited to net income tax minus the greater of the tentative minimum tax or 25% of the excess over a threshold."},{"i":"REGOX-reg_entities-028","t":"Under IRC §38(c)(6)(E), for a corporation the dollar threshold in the credit limitation computation is increased from $25,000 to $50,000.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §38(c)(6)(E)(i)","rat":"For a corporation, the threshold amount remains $25,000."},{"i":"REGOX-reg_entities-029","t":"Under IRC §38(c)(6)(B), in the case of a controlled group, the $25,000 threshold amount is apportioned among the component members of the group.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §38(c)(6)(B)","rat":"For a controlled group, the $25,000 threshold is apportioned among the members."},{"i":"REGOX-reg_entities-030","t":"Under IRC §38(c)(6)(A), a married individual filing a separate return is generally entitled to a full $25,000 threshold, the same as a single filer.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §38(c)(6)(A)","rat":"For married individuals filing separately, the threshold is generally reduced to $12,500."},{"i":"REGOX-reg_entities-031","t":"Under IRC §38(d)(1), the order in which credits listed in section 38(b) are used is determined by the order in which they are listed in that subsection as of the close of the taxable year the credit is used.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §38(d)(1)","rat":"Credits are used in the order listed in §38(b)."},{"i":"REGMC-reg_entities-004","t":"Under IRC §11(b), what is the tax rate imposed on the taxable income of a C corporation?","c":"A","mc":{"s":"Under IRC §11(b), what is the tax rate imposed on the taxable income of a C corporation?","d":"","o":["15 percent","21 percent","28 percent","35 percent"],"a":2,"cite":"26 U.S.C. §11(b)","rat":"The corporate tax rate is a flat 21%."}},{"i":"REGMC-reg_entities-005","t":"Under IRC §243(c)(1), what dividends-received deduction percentage applies to a dividend received from a 20-percent owned corporation (that is not a qualifying dividend under (a)(3))?","c":"A","mc":{"s":"Under IRC §243(c)(1), what dividends-received deduction percentage applies to a dividend received from a 20-percent owned corporation (that is not a qualifying dividend under (a)(3))?","d":"","o":["50 percent","65 percent","80 percent","100 percent"],"a":2,"cite":"26 U.S.C. §243(c)(1)","rat":"Dividends from a corporation owned 20% or more qualify for a 65% DRD rate."}},{"i":"REGMC-reg_entities-006","t":"Which of the following is expressly NOT deductible under IRC §162(a), by virtue of section 162(b)?","c":"A","mc":{"s":"Which of the following is expressly NOT deductible under IRC §162(a), by virtue of section 162(b)?","d":"","o":["Reasonable salary paid for services actually rendered","Travel expenses while away from home in pursuit of a trade or business","A contribution or gift that would be allowable as a deduction under section 170","Rent paid as a condition to continued use of property in the trade or business"],"a":3,"cite":"26 U.S.C. §162(b)","rat":"A contribution qualifying under §170 cannot instead be deducted under §162(a)."}},{"i":"REGMC-reg_entities-007","t":"For a net operating loss (other than a farming loss or certain insurance company loss) arising in a taxable year beginning after December 31, 2020, which carryback/carryforward treatment applies under IRC §172(b)(1)(A)?","c":"A","mc":{"s":"For a net operating loss (other than a farming loss or certain insurance company loss) arising in a taxable year beginning after December 31, 2020, which carryback/carryforward treatment applies under IRC §172(b)(1)(A)?","d":"","o":["A 2-year carryback and a 20-year carryforward","No carryback; carryforward to each succeeding taxable year","A 5-year carryback and a 20-year carryforward","No carryback or carryforward is permitted"],"a":2,"cite":"26 U.S.C. §172(b)(1)(A)","rat":"NOLs arising after 2017 generally allow only carryforward."}},{"i":"REGMC-reg_entities-008","t":"Under IRC §1211(a), a corporation's capital losses for the taxable year may be deducted:","c":"A","mc":{"s":"Under IRC §1211(a), a corporation's capital losses for the taxable year may be deducted:","d":"","o":["In full against ordinary income","Only to the extent of the corporation's capital gains for the year","Up to $3,000 in excess of capital gains","Up to $3,000, with any excess carried forward indefinitely"],"a":2,"cite":"26 U.S.C. §1211(a)","rat":"A corporation may deduct capital losses only against capital gains."}},{"i":"REGMC-reg_entities-009","t":"Under IRC §172(b)(1)(B)(i), the carryback period for a farming loss is:","c":"A","mc":{"s":"Under IRC §172(b)(1)(B)(i), the carryback period for a farming loss is:","d":"","o":["1 taxable year","2 taxable years","5 taxable years","10 taxable years"],"a":2,"cite":"26 U.S.C. §172(b)(1)(B)(i)","rat":"The carryback period for a farming loss is 2 years."}},{"i":"REGMC-reg_entities-010","t":"Under IRC §38(a), the general business credit allowed for the taxable year equals the sum of which items?","c":"A","mc":{"s":"Under IRC §38(a), the general business credit allowed for the taxable year equals the sum of which items?","d":"","o":["The current year business credit only","Business credit carryforwards, the current year business credit, and business credit carrybacks","Business credit carryforwards only","Business credit carrybacks and the current year business credit only"],"a":2,"cite":"26 U.S.C. §38(a)","rat":"The general business credit is the sum of carryforward, current-year, and carryback amounts."}},{"i":"REGMC-reg_entities-011","t":"Which of the following credits is listed under IRC §38(b) as part of the current year business credit?","c":"A","mc":{"s":"Which of the following credits is listed under IRC §38(b) as part of the current year business credit?","d":"","o":["The earned income credit","The foreign tax credit under section 901","The research credit determined under section 41(a)","The child tax credit"],"a":3,"cite":"26 U.S.C. §38(b)(4)","rat":"The research credit under §41 is one of the items listed in §38(b)."}},{"i":"REGMC-reg_entities-012","t":"Under IRC §38(c)(6)(E), for a corporation, the dollar threshold used in the credit limitation computation is:","c":"A","mc":{"s":"Under IRC §38(c)(6)(E), for a corporation, the dollar threshold used in the credit limitation computation is:","d":"","o":["Eliminated entirely","Reduced to $12,500","Retained at $25,000","Increased to $50,000"],"a":3,"cite":"26 U.S.C. §38(c)(6)(E)(i)","rat":"For a corporation, the threshold amount remains $25,000."}}],"4":[{"i":"REGOX-reg_entities-032","t":"Under IRC §1361(b)(1)(C), a small business corporation may not have a nonresident alien as a shareholder.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(b)(1)(C)","rat":"A nonresident alien cannot be an S corporation shareholder."},{"i":"REGOX-reg_entities-033","t":"Under IRC §1361(c)(2)(A)(i), a trust all of which is treated as owned by an individual who is a citizen or resident of the United States may be an S corporation shareholder.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(c)(2)(A)(i)","rat":"A grantor trust treated as owned by a U.S. citizen or resident can be an eligible shareholder."},{"i":"REGOX-reg_entities-034","t":"Under IRC §1361(c)(2)(A)(ii), a trust that was a grantor trust immediately before the deemed owner's death may continue as an eligible S corporation shareholder for an unlimited period after the owner's death.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(c)(2)(A)(ii)","rat":"Eligible shareholder status continues for only the 2-year period after death."},{"i":"REGOX-reg_entities-035","t":"Under IRC §1361(c)(6), an organization described in section 501(c)(3) and exempt from tax under section 501(a) may be a shareholder of an S corporation.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(c)(6)","rat":"A §501(c)(3) tax-exempt organization can be an eligible S corporation shareholder."},{"i":"REGOX-reg_entities-036","t":"Under IRC §1361(b)(1)(B), a partnership generally may be a shareholder of an S corporation without restriction.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(b)(1)(B)","rat":"A person other than an individual, estate, certain trusts, or certain tax-exempt organizations (including a partnership) generally cannot be a shareholder."},{"i":"REGOX-reg_entities-037","t":"Under IRC §1361(c)(1)(A), a husband and wife are treated as one shareholder for purposes of the 100-shareholder limit.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(c)(1)(A)","rat":"A husband and wife are treated as a single shareholder for the shareholder-count limit."},{"i":"REGOX-reg_entities-038","t":"Under IRC §1361(c)(2)(A)(v), an electing small business trust (ESBT) may be a shareholder of an S corporation.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(c)(2)(A)(v)","rat":"An electing small business trust (ESBT) can be an eligible shareholder."},{"i":"REGOX-reg_entities-039","t":"Under IRC §1361(b)(1)(A), a small business corporation may not have more than 100 shareholders.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(b)(1)(A)","rat":"A small business corporation may not have more than 100 shareholders."},{"i":"REGOX-reg_entities-040","t":"Under IRC §1361(b)(1)(D), a small business corporation may not have more than 1 class of stock.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(b)(1)(D)","rat":"A small business corporation may issue only one class of stock."},{"i":"REGOX-reg_entities-041","t":"Under IRC §1361(b)(1), a corporation organized under the laws of a foreign country may qualify as a small business corporation as long as it meets the other subsection (b)(1) requirements.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(b)(1)","rat":"Small business corporation status requires the entity to be a domestic corporation."},{"i":"REGOX-reg_entities-042","t":"Under IRC §1361(b)(2)(A), a financial institution that uses the reserve method of accounting for bad debts described in section 585 is an ineligible corporation for S corporation purposes.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(b)(2)(A)","rat":"A financial institution using the §585 reserve method is an ineligible corporation."},{"i":"REGOX-reg_entities-043","t":"Under IRC §1361(c)(4), a corporation is not treated as having more than one class of stock solely because there are differences in voting rights among shares of common stock.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(c)(4)","rat":"Differences in voting rights among shares of common stock alone do not create a second class of stock."},{"i":"REGOX-reg_entities-044","t":"Under IRC §1361(c)(5)(A), straight debt meeting the statutory safe harbor is treated as a second class of stock.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(c)(5)(A)","rat":"Straight debt that meets the requirements is not treated as a second class of stock."},{"i":"REGOX-reg_entities-045","t":"Under IRC §1361(b)(2)(C), a DISC or former DISC is an ineligible corporation and cannot elect S corporation status.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(b)(2)(C)","rat":"A DISC or former DISC is an ineligible corporation."},{"i":"REGOX-reg_entities-046","t":"Under IRC §1361(b)(2)(B), an insurance company subject to tax under subchapter L is an ineligible corporation for S corporation purposes.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1361(b)(2)(B)","rat":"An insurance company taxed under subchapter L is an ineligible corporation."},{"i":"REGOX-reg_entities-047","t":"Under IRC §1362(d)(1)(B), an S election may be revoked only if shareholders holding more than one-half of the corporation's shares consent to the revocation.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1362(d)(1)(B)","rat":"Revocation requires the consent of shareholders holding a majority of the outstanding shares."},{"i":"REGOX-reg_entities-048","t":"Under IRC §1362(d)(1)(C)(i), a revocation made on or before the 15th day of the 3rd month of the taxable year is effective on the first day of that taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1362(d)(1)(C)(i)","rat":"A revocation made on or before the 15th day of the 3rd month is effective as of the first day of that tax year."},{"i":"REGOX-reg_entities-049","t":"Under IRC §1362(d)(1)(C)(ii), a revocation made after the 15th day of the 3rd month of the taxable year is effective retroactively on the first day of that same taxable year.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1362(d)(1)(C)(ii)","rat":"A revocation made after that date is generally effective as of the first day of the following tax year."},{"i":"REGOX-reg_entities-050","t":"Under IRC §1362(d)(2)(A), an S election terminates automatically whenever the corporation ceases to be a small business corporation.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1362(d)(2)(A)","rat":"The S election automatically terminates upon failing to meet the small business corporation requirements."},{"i":"REGOX-reg_entities-051","t":"Under IRC §1362(d)(3)(A)(i), an S election terminates if the corporation has accumulated earnings and profits at the close of each of 3 consecutive taxable years and more than 25 percent of its gross receipts for each of those years is passive investment income.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1362(d)(3)(A)(i)","rat":"The S election terminates if the corporation has accumulated earnings and profits for 3 consecutive years and passive investment income exceeds 25% in each of those years."},{"i":"REGOX-reg_entities-052","t":"Under IRC §1362(d)(3)(A)(i), the passive-investment-income termination rule applies even if the corporation has no accumulated earnings and profits.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1362(d)(3)(A)(i)","rat":"This termination rule requires having accumulated earnings and profits (E&P) as of the close of each tax year."},{"i":"REGOX-reg_entities-053","t":"Under IRC §1362(g), after a termination of S status, the corporation generally may not re-elect S status before its 5th taxable year beginning after the first taxable year for which the termination was effective, absent IRS consent.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1362(g)","rat":"After a termination, re-election generally requires 5 years to pass, absent IRS consent."},{"i":"REGMC-reg_entities-013","t":"Under IRC §1361(b)(1), which of the following may NOT be a shareholder of an S corporation?","c":"A","mc":{"s":"Under IRC §1361(b)(1), which of the following may NOT be a shareholder of an S corporation?","d":"","o":["A U.S. citizen individual","An estate","A nonresident alien","A qualified subchapter S trust"],"a":3,"cite":"26 U.S.C. §1361(b)(1)(C)","rat":"A nonresident alien cannot be an S corporation shareholder."}},{"i":"REGMC-reg_entities-014","t":"Under IRC §1361(c)(2)(B)(iv), for a trust created primarily to exercise the voting power of stock transferred to it, who is treated as the shareholder for eligibility purposes?","c":"A","mc":{"s":"Under IRC §1361(c)(2)(B)(iv), for a trust created primarily to exercise the voting power of stock transferred to it, who is treated as the shareholder for eligibility purposes?","d":"","o":["The trust itself only","Each beneficiary of the trust","The trustee individually","The corporation's board of directors"],"a":2,"cite":"26 U.S.C. §1361(c)(2)(B)(iv)","rat":"For a voting trust, each beneficiary is treated as a shareholder."}},{"i":"REGMC-reg_entities-015","t":"Under IRC §1361(c)(1)(A), for purposes of the 100-shareholder limit, all members of a family (as defined) are treated as:","c":"A","mc":{"s":"Under IRC §1361(c)(1)(A), for purposes of the 100-shareholder limit, all members of a family (as defined) are treated as:","d":"","o":["A single shareholder","Separate shareholders, one per member","Ineligible shareholders","Two shareholders regardless of family size"],"a":1,"cite":"26 U.S.C. §1361(c)(1)(A)","rat":"All members of a family are treated as a single shareholder."}},{"i":"REGMC-reg_entities-016","t":"Under IRC §1361(b)(1)(A), what is the maximum number of shareholders a small business corporation may have?","c":"A","mc":{"s":"Under IRC §1361(b)(1)(A), what is the maximum number of shareholders a small business corporation may have?","d":"","o":["35","75","100","500"],"a":3,"cite":"26 U.S.C. §1361(b)(1)(A)","rat":"The shareholder limit for a small business corporation is 100."}},{"i":"REGMC-reg_entities-017","t":"Under IRC §1361(b)(2), which of the following is an 'ineligible corporation' that cannot elect S status?","c":"A","mc":{"s":"Under IRC §1361(b)(2), which of the following is an 'ineligible corporation' that cannot elect S status?","d":"","o":["A manufacturing corporation with 50 shareholders","An insurance company subject to tax under subchapter L","A corporation with two classes of common stock differing only in voting rights","A corporation with outstanding straight debt meeting the section 1361(c)(5) safe harbor"],"a":2,"cite":"26 U.S.C. §1361(b)(2)(B)","rat":"An insurance company taxed under subchapter L is an ineligible corporation."}},{"i":"REGMC-reg_entities-018","t":"Under IRC §1361(b)(1)(D), which of the following would cause a corporation to have more than one class of stock?","c":"A","mc":{"s":"Under IRC §1361(b)(1)(D), which of the following would cause a corporation to have more than one class of stock?","d":"","o":["Common stock with different voting rights across shares","Straight debt meeting the section 1361(c)(5) safe harbor","Outstanding stock with different rights to distribution and liquidation proceeds","None of the above"],"a":3,"cite":"26 U.S.C. §1361(b)(1)(D)","rat":"Stock with different distribution or liquidation rights constitutes a second class of stock."}},{"i":"REGMC-reg_entities-019","t":"Under IRC §1362(d)(1)(B), an S election may be revoked only if consent is obtained from shareholders holding:","c":"A","mc":{"s":"Under IRC §1362(d)(1)(B), an S election may be revoked only if consent is obtained from shareholders holding:","d":"","o":["All of the outstanding shares","More than one-half of the shares","At least two-thirds of the shares","At least 80 percent of the shares"],"a":2,"cite":"26 U.S.C. §1362(d)(1)(B)","rat":"Revocation requires the consent of shareholders holding a majority of the outstanding shares."}},{"i":"REGMC-reg_entities-020","t":"Under IRC §1362(d)(3), termination of S status due to excess passive investment income requires:","c":"A","mc":{"s":"Under IRC §1362(d)(3), termination of S status due to excess passive investment income requires:","d":"","o":["1 year of excess passive investment income, regardless of earnings and profits","3 consecutive years of excess passive investment income and accumulated earnings and profits at the close of each such year","5 consecutive years of excess passive investment income","Excess passive investment income in any single year, with no earnings and profits requirement"],"a":2,"cite":"26 U.S.C. §1362(d)(3)(A)(i)","rat":"Both the 3-consecutive-year requirement and holding accumulated earnings and profits are needed."}},{"i":"REGMC-reg_entities-021","t":"Under IRC §1362(g), following a termination of S status, a corporation generally may not re-elect S status before:","c":"A","mc":{"s":"Under IRC §1362(g), following a termination of S status, a corporation generally may not re-elect S status before:","d":"","o":["The next taxable year","Its 3rd taxable year after termination","Its 5th taxable year beginning after the first taxable year for which the termination was effective","It may never re-elect S status"],"a":3,"cite":"26 U.S.C. §1362(g)","rat":"Re-election is allowed without IRS consent starting with the 5th tax year after termination."}}],"5":[{"i":"REGOX-reg_entities-054","t":"Under IRC §1363(a), an S corporation is generally not subject to the taxes imposed by chapter 1.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1363(a)","rat":"An S corporation generally is not subject to corporate-level income tax."},{"i":"REGOX-reg_entities-055","t":"Under IRC §1363(b)(1), the items described in section 1366(a)(1)(A) must be separately stated by the S corporation.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1363(b)(1)","rat":"Items described in §1366(a)(1)(A) must be separately stated."},{"i":"REGOX-reg_entities-056","t":"Under IRC §1363(b), an S corporation's taxable income is computed in the same manner as a partnership's taxable income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1363(b)","rat":"An S corporation's taxable income is computed in the same manner as an individual's."},{"i":"REGOX-reg_entities-057","t":"Under IRC §1366(a)(2), 'nonseparately computed income or loss' means gross income minus the deductions allowed to the corporation, determined by excluding all items required to be separately stated.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1366(a)(2)","rat":"Nonseparately computed income (loss) is gross income minus deductions, excluding separately stated items."},{"i":"REGOX-reg_entities-058","t":"Under IRC §1366(b), the character of an item in a shareholder's pro rata share is determined as if the item were realized directly from the source from which the corporation realized it.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1366(b)","rat":"The character of an item is determined as if realized directly by the shareholder (pass-through/conduit principle)."},{"i":"REGOX-reg_entities-059","t":"Under IRC §1366(d)(1), a shareholder may take into account losses and deductions passed through from an S corporation without regard to the shareholder's basis in stock or debt.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1366(d)(1)","rat":"Losses and deductions are limited to the sum of stock basis and debt basis."},{"i":"REGOX-reg_entities-060","t":"Under IRC §1363(b)(4), section 291 applies to an S corporation that was a C corporation for any of the 3 immediately preceding taxable years.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1363(b)(4)","rat":"§1291 applies to an S corporation that was a C corporation within the preceding 3 years."},{"i":"REGOX-reg_entities-061","t":"Under IRC §1368(c)(1), a distribution by an S corporation with accumulated earnings and profits is treated, to the extent it does not exceed the accumulated adjustments account, in the manner provided by subsection (b).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1368(c)(1)","rat":"A distribution within the AAA is treated under the method described in (b) (e.g., reducing basis)."},{"i":"REGOX-reg_entities-062","t":"Under IRC §1368(e)(1)(A), no adjustment is made to the accumulated adjustments account for income (and related expenses) exempt from tax under this title.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1368(e)(1)(A)","rat":"Tax-exempt income (and related expenses) is excluded from AAA adjustments."},{"i":"REGOX-reg_entities-063","t":"Under IRC §1368(e)(1)(A), the accumulated adjustments account is adjusted for Federal taxes attributable to any taxable year in which the corporation was a C corporation.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1368(e)(1)(A)","rat":"Federal taxes attributable to a C corporation year are excluded from AAA adjustments."},{"i":"REGOX-reg_entities-064","t":"Under IRC §1368(e)(1)(A), because the phrase 'but not below zero' in section 1367(a)(2) is disregarded, the accumulated adjustments account may be reduced below zero, unlike a shareholder's stock basis.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1368(e)(1)(A)","rat":"AAA differs from stock basis in that the \"not below zero\" rule does not apply, so AAA can go negative."},{"i":"REGOX-reg_entities-065","t":"Under IRC §1368(e)(1)(C)(i), the balance of the accumulated adjustments account at the close of the taxable year, for purposes of distributions made during that year, is determined without regard to any net negative adjustment for that year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1368(e)(1)(C)(i)","rat":"For purposes of a current-year distribution, the AAA balance is computed without regard to net decrease adjustments."},{"i":"REGOX-reg_entities-066","t":"Under IRC §1368(c)(2), the portion of a distribution remaining after applying the accumulated adjustments account rule is treated as a dividend to the extent it does not exceed the corporation's accumulated earnings and profits.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1368(c)(2)","rat":"A distribution in excess of AAA is treated as a dividend to the extent of accumulated earnings and profits."},{"i":"REGOX-reg_entities-067","t":"Under IRC §1368(e)(3)(A), an S corporation may elect to have distributions treated as coming from earnings and profits before the accumulated adjustments account, with the consent of a majority of its affected shareholders.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1368(e)(3)(A)","rat":"This election requires the consent of all affected shareholders."},{"i":"REGMC-reg_entities-022","t":"Under IRC §1363(b), an S corporation's taxable income is computed in the same manner as that of:","c":"A","mc":{"s":"Under IRC §1363(b), an S corporation's taxable income is computed in the same manner as that of:","d":"","o":["A C corporation","A partnership","An individual","A trust"],"a":3,"cite":"26 U.S.C. §1363(b)","rat":"An S corporation's taxable income is computed in the same manner as an individual's."}},{"i":"REGMC-reg_entities-023","t":"Under IRC §1366(d)(1), a shareholder's losses and deductions passed through from an S corporation cannot exceed:","c":"A","mc":{"s":"Under IRC §1366(d)(1), a shareholder's losses and deductions passed through from an S corporation cannot exceed:","d":"","o":["The shareholder's share of the corporation's accumulated adjustments account","The sum of the shareholder's basis in stock and in corporation debt","The shareholder's original capital contribution only","There is no limitation under section 1366"],"a":2,"cite":"26 U.S.C. §1366(d)(1)","rat":"The limit on losses and deductions is the sum of stock basis and debt basis."}},{"i":"REGMC-reg_entities-024","t":"Under IRC §1366(a)(1)(A), which type of item must an S corporation separately state to its shareholders?","c":"A","mc":{"s":"Under IRC §1366(a)(1)(A), which type of item must an S corporation separately state to its shareholders?","d":"","o":["Cost of goods sold","Items such as capital gains and losses, the separate treatment of which could affect a shareholder's tax liability","Employee wage expense","Rent expense for the corporation's office"],"a":2,"cite":"26 U.S.C. §1366(a)(1)(A)","rat":"An item that could affect any shareholder's tax liability must be separately stated."}},{"i":"REGMC-reg_entities-025","t":"Under IRC §1368(c), a distribution by an S corporation with accumulated earnings and profits is treated, to the extent it does not exceed the accumulated adjustments account, in the manner provided by:","c":"A","mc":{"s":"Under IRC §1368(c), a distribution by an S corporation with accumulated earnings and profits is treated, to the extent it does not exceed the accumulated adjustments account, in the manner provided by:","d":"","o":["Subsection (b), as if the corporation had no earnings and profits","Section 301(c) dividend rules exclusively","Section 1366(d)","Section 1367(b)(2)"],"a":1,"cite":"26 U.S.C. §1368(c)(1)","rat":"A distribution within the AAA is treated under the method in (b)."}},{"i":"REGMC-reg_entities-026","t":"Under IRC §1368(e)(1)(A), which item is excluded from the adjustment to the accumulated adjustments account?","c":"A","mc":{"s":"Under IRC §1368(e)(1)(A), which item is excluded from the adjustment to the accumulated adjustments account?","d":"","o":["Ordinary business income","Income exempt from tax (and related expenses)","Nonseparately stated losses","Nondeductible, noncapital expenses"],"a":2,"cite":"26 U.S.C. §1368(e)(1)(A)","rat":"Tax-exempt income and related expenses are excluded from AAA adjustments."}},{"i":"REGMC-reg_entities-027","t":"Under IRC §1368(e)(1)(C), for purposes of distributions made during a taxable year, the accumulated adjustments account balance at the close of the year is determined:","c":"A","mc":{"s":"Under IRC §1368(e)(1)(C), for purposes of distributions made during a taxable year, the accumulated adjustments account balance at the close of the year is determined:","d":"","o":["Including any net negative adjustment for the year","Without regard to any net negative adjustment for the year","Only after all distributions for the year have been made","By reference solely to the corporation's earnings and profits"],"a":2,"cite":"26 U.S.C. §1368(e)(1)(C)(i)","rat":"The current year's net decrease adjustment is excluded when computing the AAA balance for distribution purposes."}}],"6":[{"i":"REGOX-reg_entities-068","t":"Under IRC §1367(a)(1)(A), a shareholder's stock basis is increased by the items of income described in section 1366(a)(1)(A).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(a)(1)(A)","rat":"Separately stated income items increase stock basis."},{"i":"REGOX-reg_entities-069","t":"Under IRC §1367(a)(2)(A), a shareholder's stock basis is decreased (but not below zero) by distributions not includible in the shareholder's income under section 1368.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(a)(2)(A)","rat":"A distribution excluded from income under §1368 decreases stock basis (not below zero)."},{"i":"REGOX-reg_entities-070","t":"Under IRC §1367(a)(2), a shareholder's stock basis may be reduced below zero to reflect a loss passed through in excess of basis.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(a)(2)","rat":"A decrease in stock basis cannot go below zero."},{"i":"REGOX-reg_entities-071","t":"Under IRC §1367(a)(2)(D), a shareholder's stock basis is decreased by any expense of the corporation not deductible in computing its taxable income and not properly chargeable to capital account.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(a)(2)(D)","rat":"Nondeductible, noncapital expenses also decrease stock basis."},{"i":"REGOX-reg_entities-072","t":"Under IRC §1367(a)(1)(C), a shareholder's stock basis is increased by the excess of the deduction for depletion over the basis of the property subject to depletion.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(a)(1)(C)","rat":"Basis increases by the amount a depletion deduction exceeds the property's basis."},{"i":"REGOX-reg_entities-073","t":"Under IRC §1367(a)(2), the decrease in a shareholder's stock basis for a charitable contribution of property by the corporation equals the property's fair market value on the date of contribution.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(a)(2)","rat":"The basis decrease is the shareholder's proportionate share of the property's basis, not fair market value."},{"i":"REGOX-reg_entities-074","t":"Under IRC §1367(a)(1)(B), a shareholder's stock basis is increased by nonseparately computed income determined under section 1366(a)(1)(B).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(a)(1)(B)","rat":"Nonseparately computed income also increases stock basis."},{"i":"REGOX-reg_entities-075","t":"Under IRC §1367(b)(2)(A), if losses and deductions exceed the amount needed to reduce a shareholder's stock basis to zero, the excess is applied to reduce (but not below zero) the shareholder's basis in the corporation's indebtedness to the shareholder.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(b)(2)(A)","rat":"After stock basis reaches zero, an excess loss reduces debt basis (not below zero)."},{"i":"REGOX-reg_entities-076","t":"Under IRC §1367(b)(2)(B), once a shareholder's debt basis has been reduced, a net increase for a subsequent taxable year is first applied to restore that reduction before it may increase the shareholder's stock basis.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(b)(2)(B)","rat":"A net increase in a later year is first used to restore debt basis, and then increases stock basis."},{"i":"REGOX-reg_entities-077","t":"Under IRC §1367(b)(2)(B), a net increase in basis items in a later year is applied to increase the shareholder's stock basis before restoring any prior reduction in debt basis.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(b)(2)(B)","rat":"A net increase is used to restore any reduction in debt basis before restoring stock basis."},{"i":"REGOX-reg_entities-078","t":"Under IRC §1367(b)(2)(B), the debt basis restoration rule applies to reductions occurring in taxable years beginning after December 31, 1982.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(b)(2)(B)","rat":"The debt-basis restoration rule applies to reductions in tax years beginning after December 31, 1982."},{"i":"REGOX-reg_entities-079","t":"Under IRC §1367(b)(2)(A), a shareholder's debt basis, once reduced, can never be restored in a later taxable year.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(b)(2)(B)","rat":"Under (b)(2)(B), debt basis may be restored by a later year's net increase."},{"i":"REGOX-reg_entities-080","t":"Under IRC §1367(a)(2), a shareholder's stock basis (not debt basis) is reduced first by losses and other decreases listed in subsection (a)(2), before any excess is applied to reduce debt basis under subsection (b)(2)(A).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1367(a)(2), §1367(b)(2)(A)","rat":"Losses, etc., first reduce stock basis, and only the excess reduces debt basis."},{"i":"REGMC-reg_entities-028","t":"Under IRC §1367(a)(2), a shareholder's stock basis in an S corporation is decreased (but not below zero) for which of the following?","c":"A","mc":{"s":"Under IRC §1367(a)(2), a shareholder's stock basis in an S corporation is decreased (but not below zero) for which of the following?","d":"","o":["Nonseparately computed income","Items of loss and deduction described in section 1366(a)(1)(A)","Capital contributions made during the year","Increases in the shareholder's share of corporate debt"],"a":2,"cite":"26 U.S.C. §1367(a)(2)(B)","rat":"Separately stated loss and deduction items decrease stock basis."}},{"i":"REGMC-reg_entities-029","t":"Under IRC §1367(a)(2) (flush language), the amount by which a shareholder's stock basis is reduced for a charitable contribution of property by the S corporation is:","c":"A","mc":{"s":"Under IRC §1367(a)(2) (flush language), the amount by which a shareholder's stock basis is reduced for a charitable contribution of property by the S corporation is:","d":"","o":["The property's fair market value","The shareholder's pro rata share of the property's adjusted basis","Zero; no basis reduction occurs","The full amount of the charitable contribution deduction claimed by the shareholder"],"a":2,"cite":"26 U.S.C. §1367(a)(2)","rat":"The basis decrease is the shareholder's proportionate share of the property's basis, not fair market value."}},{"i":"REGMC-reg_entities-030","t":"Which item increases a shareholder's stock basis under IRC §1367(a)(1)?","c":"A","mc":{"s":"Which item increases a shareholder's stock basis under IRC §1367(a)(1)?","d":"","o":["Distributions not includible in income under section 1368","Nonseparately computed income determined under section 1366(a)(1)(B)","Nondeductible, noncapital expenses of the corporation","Nonseparately computed loss"],"a":2,"cite":"26 U.S.C. §1367(a)(1)(B)","rat":"Nonseparately computed income increases stock basis."}},{"i":"REGMC-reg_entities-031","t":"Under IRC §1367(b)(2)(A), a shareholder's basis in S corporation debt is reduced only after:","c":"A","mc":{"s":"Under IRC §1367(b)(2)(A), a shareholder's basis in S corporation debt is reduced only after:","d":"","o":["The shareholder's stock basis has been reduced to zero","The corporation terminates its S election","The debt is fully repaid","The corporation's accumulated adjustments account is exhausted"],"a":1,"cite":"26 U.S.C. §1367(b)(2)(A)","rat":"A decrease in debt basis occurs only after stock basis has been reduced to zero."}},{"i":"REGMC-reg_entities-032","t":"Under IRC §1367(b)(2)(B), when a shareholder's debt basis has previously been reduced, a net increase for a later taxable year is applied:","c":"A","mc":{"s":"Under IRC §1367(b)(2)(B), when a shareholder's debt basis has previously been reduced, a net increase for a later taxable year is applied:","d":"","o":["To increase stock basis first, then debt basis","To restore the debt basis reduction before increasing stock basis","Only to increase stock basis; debt basis reductions are permanent","Proportionately between stock and debt basis, with no ordering rule"],"a":2,"cite":"26 U.S.C. §1367(b)(2)(B)","rat":"A net increase is applied first to restore debt basis."}},{"i":"REGMC-reg_entities-033","t":"Under IRC §1367(b)(2)(A), reductions in a shareholder's debt basis are limited such that debt basis:","c":"A","mc":{"s":"Under IRC §1367(b)(2)(A), reductions in a shareholder's debt basis are limited such that debt basis:","d":"","o":["May be reduced below zero if losses are large enough","May not be reduced below zero","Is unaffected by S corporation losses","Can be restored only through additional cash loans, never through later income"],"a":2,"cite":"26 U.S.C. §1367(b)(2)(A)","rat":"A decrease in debt basis cannot go below zero."}}],"7":[{"i":"REGOX-reg_entities-081","t":"Under IRC §702(a)(8), each partner separately takes into account his distributive share of the partnership's taxable income or loss, exclusive of items requiring separate computation under the other paragraphs of section 702(a).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §702(a)(8)","rat":"Remaining taxable income (loss), excluding separately stated items, is allocated to each partner."},{"i":"REGOX-reg_entities-082","t":"Under IRC §702(a)(4), each partner separately takes into account his distributive share of the partnership's charitable contributions.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §702(a)(4)","rat":"A charitable contribution is a separately stated item for each partner."},{"i":"REGOX-reg_entities-083","t":"Under IRC §703(a), a partnership's taxable income is computed in the same manner as a corporation's taxable income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §703(a)","rat":"A partnership's taxable income is computed in the same manner as an individual's."},{"i":"REGOX-reg_entities-084","t":"Under IRC §703(a)(2)(D), the net operating loss deduction under section 172 is not allowed to the partnership itself.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §703(a)(2)(D)","rat":"The NOL deduction is not allowed at the partnership level."},{"i":"REGOX-reg_entities-085","t":"Under IRC §703(a)(2)(C), the deduction for charitable contributions under section 170 is not allowed to the partnership itself.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §703(a)(2)(C)","rat":"The charitable contribution deduction is not allowed at the partnership level and is instead passed through to each partner."},{"i":"REGOX-reg_entities-086","t":"Under IRC §707(c), a guaranteed payment to a partner for services, determined without regard to partnership income, is treated as a payment to a person who is not a partner for purposes of section 61(a) and, subject to section 263, section 162(a).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §707(c)","rat":"A guaranteed payment is treated as a payment to a non-partner for §61(a) and §162(a) purposes."},{"i":"REGOX-reg_entities-087","t":"Under IRC §707(c), a guaranteed payment is treated as a payment to a non-partner for all purposes of the Internal Revenue Code.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §707(c)","rat":"Non-partner treatment applies only for §61(a) and §162(a) purposes (subject to §263)."},{"i":"REGOX-reg_entities-088","t":"Under IRC §702(b), the character of an item included in a partner's distributive share is determined as if the item were realized directly from the source from which the partnership realized it.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §702(b)","rat":"The character of an item retains the source character it had at the partnership level."},{"i":"REGMC-reg_entities-034","t":"Under IRC §703(a), the taxable income of a partnership is computed in the same manner as in the case of:","c":"A","mc":{"s":"Under IRC §703(a), the taxable income of a partnership is computed in the same manner as in the case of:","d":"","o":["A C corporation","An individual","An S corporation","A trust"],"a":2,"cite":"26 U.S.C. §703(a)","rat":"A partnership's taxable income is computed in the same manner as an individual's."}},{"i":"REGMC-reg_entities-035","t":"Under IRC §707(c), a guaranteed payment to a partner for services is treated as a payment to a person who is not a partner for purposes of:","c":"A","mc":{"s":"Under IRC §707(c), a guaranteed payment to a partner for services is treated as a payment to a person who is not a partner for purposes of:","d":"","o":["All provisions of the Internal Revenue Code","Section 61(a) gross income and, subject to section 263, section 162(a)","Only the self-employment tax provisions","Only the partnership basis provisions of section 705"],"a":2,"cite":"26 U.S.C. §707(c)","rat":"Non-partner treatment of a guaranteed payment is limited to §61(a) and §162(a)."}},{"i":"REGMC-reg_entities-036","t":"Under IRC §702(a), which of the following items must a partner separately take into account, rather than as part of ordinary partnership income?","c":"A","mc":{"s":"Under IRC §702(a), which of the following items must a partner separately take into account, rather than as part of ordinary partnership income?","d":"","o":["Cost of goods sold","Gains and losses from sales of capital assets held for more than 1 year","Employee wage expense","Rent expense on the partnership's office"],"a":2,"cite":"26 U.S.C. §702(a)(2)","rat":"Long-term capital gain or loss is a separately stated item for each partner."}}],"8":[{"i":"REGOX-reg_entities-089","t":"Under IRC §705(a)(1)(A), a partner's basis in the partnership interest is increased by the partner's distributive share of the partnership's taxable income.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §705(a)(1)(A)","rat":"A partner's distributive share of partnership taxable income increases the partner's basis."},{"i":"REGOX-reg_entities-090","t":"Under IRC §705(a)(1)(B), a partner's basis is increased by the partner's distributive share of partnership income exempt from tax.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §705(a)(1)(B)","rat":"A distributive share of tax-exempt income also increases the partner's basis."},{"i":"REGOX-reg_entities-091","t":"Under IRC §705(a)(2), a partner's basis may be decreased below zero by the partner's distributive share of partnership losses.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §705(a)(2)","rat":"A decrease in a partner's basis cannot go below zero."},{"i":"REGOX-reg_entities-092","t":"Under IRC §722, the basis of a partnership interest acquired by a contribution of property (including money) equals the money contributed plus the adjusted basis of the contributed property, increased by any gain recognized under section 721(b).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §722","rat":"The basis of an interest acquired by contribution is cash plus the basis of contributed property (plus any recognized gain)."},{"i":"REGOX-reg_entities-093","t":"Under IRC §733, a distribution other than in liquidation of a partner's interest reduces the partner's basis in the partnership interest (not below zero) by the money distributed and the basis of distributed property other than money.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §733","rat":"A current (nonliquidating) distribution reduces the partner's basis by cash distributed and the §732 basis of distributed property (not below zero)."},{"i":"REGOX-reg_entities-094","t":"Under IRC §752(a), an increase in a partner's share of partnership liabilities is treated as a contribution of money by the partner to the partnership.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §752(a)","rat":"An increase in a partner's share of partnership liabilities is treated as a deemed cash contribution, increasing basis."},{"i":"REGOX-reg_entities-095","t":"Under IRC §752(b), a decrease in a partner's share of partnership liabilities is treated as a contribution of money by the partner to the partnership.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §752(b)","rat":"A decrease in a partner's share of partnership liabilities is treated as a deemed cash distribution by the partnership, decreasing basis."},{"i":"REGOX-reg_entities-096","t":"Under IRC §705(a)(2)(B), a partner's basis is decreased by the partner's distributive share of partnership expenditures not deductible in computing taxable income and not properly chargeable to capital account.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §705(a)(2)(B)","rat":"A partner's share of nondeductible, noncapital expenditures also decreases the partner's basis."},{"i":"REGMC-reg_entities-037","t":"Under IRC §752(a), an increase in a partner's share of partnership liabilities is treated as:","c":"A","mc":{"s":"Under IRC §752(a), an increase in a partner's share of partnership liabilities is treated as:","d":"","o":["A distribution of money to the partner","A contribution of money by the partner to the partnership","Taxable gain to the partner","No effect on the partner's basis"],"a":2,"cite":"26 U.S.C. §752(a)","rat":"An increase in a partner's share of liabilities is treated as a deemed cash contribution, increasing basis."}},{"i":"REGMC-reg_entities-038","t":"Under IRC §722, the basis of a partnership interest acquired by a contribution of property equals the money contributed plus:","c":"A","mc":{"s":"Under IRC §722, the basis of a partnership interest acquired by a contribution of property equals the money contributed plus:","d":"","o":["The fair market value of the contributed property","The adjusted basis of the contributed property to the contributing partner, increased by gain recognized under section 721(b)","The partnership's aggregate basis in all its assets","Zero, unless cash is contributed"],"a":2,"cite":"26 U.S.C. §722","rat":"The basis of a contributed interest is cash plus the basis of contributed property (plus any recognized gain)."}},{"i":"REGMC-reg_entities-039","t":"Under IRC §733, a current (non-liquidating) distribution from a partnership reduces the distributee partner's basis in the partnership interest by:","c":"A","mc":{"s":"Under IRC §733, a current (non-liquidating) distribution from a partnership reduces the distributee partner's basis in the partnership interest by:","d":"","o":["The fair market value of all property received","The money distributed plus the section 732 basis of distributed property other than money","Only the money distributed, never property","The partnership's total liabilities"],"a":2,"cite":"26 U.S.C. §733","rat":"A current (nonliquidating) distribution reduces the partner's basis by cash distributed and the §732 basis of distributed property."}}],"9":[{"i":"REGOX-reg_entities-097","t":"Under IRC §7701(a)(2), the term 'partnership' includes a syndicate, group, pool, joint venture, or other unincorporated organization through which a business, financial operation, or venture is carried on, provided it is not, within the meaning of the Code, a trust, estate, or corporation.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7701(a)(2)","rat":"The statutory definition of a partnership broadly includes unincorporated organizations."},{"i":"REGOX-reg_entities-098","t":"Under IRC §7701(a)(3), the term 'corporation' includes associations, joint-stock companies, and insurance companies.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7701(a)(3)","rat":"The statutory definition of a corporation includes associations, joint-stock companies, and insurance companies."},{"i":"REGOX-reg_entities-099","t":"Under IRC §7701(a)(2), the statutory term 'partnership' includes an unincorporated organization even if it is treated as a trust or estate under the Code.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7701(a)(2)","rat":"An organization properly classified as a trust, estate, or corporation is excluded from the partnership definition."},{"i":"REGOX-reg_entities-100","t":"Under IRC §7701(a)(4), the term 'domestic' when applied to a corporation or partnership means created or organized in the United States or under the law of the United States or of any State.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7701(a)(4)","rat":"\"Domestic\" means created or organized in the United States or under the law of any state."},{"i":"REGOX-reg_entities-101","t":"Under IRC §7701(a)(5), the term 'foreign' when applied to a corporation or partnership means one that is not domestic.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7701(a)(5)","rat":"\"Foreign\" means not domestic."},{"i":"REGOX-reg_entities-102","t":"Under IRC §7701(a)(3), the term 'corporation' is defined to include partnerships and unincorporated joint ventures.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7701(a)(3)","rat":"This language belongs to the partnership definition ((a)(2)), not the corporation definition ((a)(3))."},{"i":"REGMC-reg_entities-040","t":"Under IRC §7701(a)(2), the statutory term 'partnership' includes:","c":"A","mc":{"s":"Under IRC §7701(a)(2), the statutory term 'partnership' includes:","d":"","o":["Only entities formed under a state partnership statute","A syndicate, group, pool, joint venture, or other unincorporated organization carrying on a business, financial operation, or venture, that is not a trust, estate, or corporation","Any corporation electing partnership treatment","Only general partnerships, not joint ventures"],"a":2,"cite":"26 U.S.C. §7701(a)(2)","rat":"The statutory definition of a partnership broadly includes unincorporated organizations."}},{"i":"REGMC-reg_entities-041","t":"Under IRC §7701(a)(3), the term 'corporation' includes:","c":"A","mc":{"s":"Under IRC §7701(a)(3), the term 'corporation' includes:","d":"","o":["Partnerships and joint ventures","Associations, joint-stock companies, and insurance companies","Sole proprietorships","Trusts and estates"],"a":2,"cite":"26 U.S.C. §7701(a)(3)","rat":"The statutory definition of a corporation includes associations, joint-stock companies, and insurance companies."}},{"i":"REGMC-reg_entities-042","t":"Under IRC §7701(a)(4) and (a)(5), a corporation or partnership is 'domestic' if it is:","c":"A","mc":{"s":"Under IRC §7701(a)(4) and (a)(5), a corporation or partnership is 'domestic' if it is:","d":"","o":["Owned entirely by U.S. citizens","Created or organized in the United States or under the law of the United States or of any State","Headquartered in the United States regardless of where organized","Registered with a U.S. securities regulator"],"a":2,"cite":"26 U.S.C. §7701(a)(4)","rat":"\"Domestic\" means organized under the law of the United States or a state."}}],"10":[{"i":"REGOX-reg_entities-103","t":"Under IRC §501(c)(3), organizations organized and operated exclusively for religious, charitable, scientific, or educational purposes may qualify for exemption if no part of net earnings inures to any private shareholder or individual.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §501(c)(3)","rat":"§501(c)(3) lists the representative categories of tax-exempt organizations (religious, charitable, scientific, educational, etc.)."},{"i":"REGOX-reg_entities-104","t":"Under IRC §501(a), an organization described in subsection (c) or (d) or in section 401(a) is exempt from taxation under subtitle A unless the exemption is denied under section 502 or 503.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §501(a)","rat":"Organizations described in (c), (d), and §401(a) are tax-exempt unless denied exemption under §502 or §503."},{"i":"REGOX-reg_entities-105","t":"Under IRC §501(b), an organization exempt under subsection (a) is exempt from tax on all of its income, including income from an unrelated trade or business.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §501(b)","rat":"Under (b), unrelated business income, among other items, is separately taxed."},{"i":"REGOX-reg_entities-106","t":"Under IRC §501(c)(4)(A), civic leagues not organized for profit but operated exclusively for the promotion of social welfare are described as exempt organizations.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §501(c)(4)(A)","rat":"A nonprofit civic organization operated exclusively for social welfare is one of the exempt categories."},{"i":"REGOX-reg_entities-107","t":"Under IRC §501(c)(6), business leagues, chambers of commerce, real estate boards, and boards of trade not organized for profit, no part of the net earnings of which inures to any private shareholder or individual, may qualify for exemption.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §501(c)(6)","rat":"A nonprofit business league, such as a chamber of commerce or real estate board, is one of the exempt categories."},{"i":"REGOX-reg_entities-108","t":"Under IRC §501(c)(3), an organization otherwise qualifying may participate or intervene in a political campaign on behalf of a candidate for public office, as long as such activity is not substantial.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §501(c)(3)","rat":"Political campaign intervention is entirely prohibited regardless of degree (unlike the \"substantial\" standard for lobbying)."},{"i":"REGOX-reg_entities-109","t":"Under IRC §501(c)(7), clubs organized for pleasure, recreation, and other nonprofitable purposes may qualify for exemption if substantially all of their activities are for such purposes and no part of net earnings inures to any private shareholder.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §501(c)(7)","rat":"A social or recreational club can also qualify as tax-exempt if it meets the requirements."},{"i":"REGOX-reg_entities-110","t":"Under IRC §501(c)(5), labor, agricultural, or horticultural organizations are listed among the organizations described in subsection (c).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §501(c)(5)","rat":"Labor, agricultural, and horticultural organizations are also among the exempt categories."},{"i":"REGMC-reg_entities-043","t":"Under IRC §501(c)(3), which of the following would disqualify an organization from exemption?","c":"A","mc":{"s":"Under IRC §501(c)(3), which of the following would disqualify an organization from exemption?","d":"","o":["Operating exclusively for scientific purposes","Net earnings that inure to the benefit of a private shareholder or individual","Being organized as a nonprofit corporation","Testing for public safety"],"a":2,"cite":"26 U.S.C. §501(c)(3)","rat":"Private inurement disqualifies an organization from tax-exempt status."}},{"i":"REGMC-reg_entities-044","t":"Under IRC §501(c)(6), which organization type is specifically listed as eligible for exemption?","c":"A","mc":{"s":"Under IRC §501(c)(6), which organization type is specifically listed as eligible for exemption?","d":"","o":["A social club organized for recreation","A chamber of commerce not organized for profit","A credit union without capital stock","A voluntary employees' beneficiary association"],"a":2,"cite":"26 U.S.C. §501(c)(6)","rat":"A chamber of commerce is a category listed under §501(c)(6)."}},{"i":"REGMC-reg_entities-045","t":"Under IRC §501(b), an organization otherwise exempt under section 501(a) is nonetheless subject to tax on:","c":"A","mc":{"s":"Under IRC §501(b), an organization otherwise exempt under section 501(a) is nonetheless subject to tax on:","d":"","o":["All of its gross receipts","Unrelated business income, to the extent provided elsewhere in the Code","Nothing; the exemption is absolute","Only its investment income"],"a":2,"cite":"26 U.S.C. §501(b)","rat":"Unrelated business income is separately taxed."}},{"i":"REGMC-reg_entities-046","t":"Which subsection of IRC §501(c) lists 'labor, agricultural, or horticultural organizations' as exempt?","c":"A","mc":{"s":"Which subsection of IRC §501(c) lists 'labor, agricultural, or horticultural organizations' as exempt?","d":"","o":["Section 501(c)(3)","Section 501(c)(5)","Section 501(c)(7)","Section 501(c)(9)"],"a":2,"cite":"26 U.S.C. §501(c)(5)","rat":"Labor, agricultural, and horticultural organizations are described in §501(c)(5)."}}]};
window.PAIRS=[{"n":2,"s":0.603,"o":{"i":"REGOX-reg_entities-010","t":"Under IRC §63(a), taxable income means gross income minus the deductions allowed by chapter 1, other than the standard deduction.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-011","t":"Under IRC §63(a), a C corporation computes taxable income as gross income minus the deductions allowed by chapter 1, other than the deduction for personal exemptions.","y":null,"e":"US CPA REG"}},{"n":2,"s":0.446,"o":{"i":"REGOX-reg_entities-018","t":"Under IRC §172(b)(1)(A)(ii)(II), a net operating loss arising in a taxable year beginning after December 31, 2017, is carried forward to each succeeding taxable year, with no expiration.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-019","t":"Under IRC §172(b)(1)(A), a net operating loss arising in a taxable year beginning after December 31, 2017 (other than a farming loss or certain insurance company loss) may be carried back 2 taxable years before being carried forward.","y":null,"e":"US CPA REG"}},{"n":4,"s":0.699,"o":{"i":"REGOX-reg_entities-048","t":"Under IRC §1362(d)(1)(C)(i), a revocation made on or before the 15th day of the 3rd month of the taxable year is effective on the first day of that taxable year.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-049","t":"Under IRC §1362(d)(1)(C)(ii), a revocation made after the 15th day of the 3rd month of the taxable year is effective retroactively on the first day of that same taxable year.","y":null,"e":"US CPA REG"}},{"n":4,"s":0.401,"o":{"i":"REGOX-reg_entities-051","t":"Under IRC §1362(d)(3)(A)(i), an S election terminates if the corporation has accumulated earnings and profits at the close of each of 3 consecutive taxable years and more than 25 percent of its gross receipts for each of those years is passive investment income.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-052","t":"Under IRC §1362(d)(3)(A)(i), the passive-investment-income termination rule applies even if the corporation has no accumulated earnings and profits.","y":null,"e":"US CPA REG"}},{"n":4,"s":0.351,"o":{"i":"REGOX-reg_entities-038","t":"Under IRC §1361(c)(2)(A)(v), an electing small business trust (ESBT) may be a shareholder of an S corporation.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-036","t":"Under IRC §1361(b)(1)(B), a partnership generally may be a shareholder of an S corporation without restriction.","y":null,"e":"US CPA REG"}},{"n":5,"s":0.343,"o":{"i":"REGOX-reg_entities-061","t":"Under IRC §1368(c)(1), a distribution by an S corporation with accumulated earnings and profits is treated, to the extent it does not exceed the accumulated adjustments account, in the manner provided by subsection (b).","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-067","t":"Under IRC §1368(e)(3)(A), an S corporation may elect to have distributions treated as coming from earnings and profits before the accumulated adjustments account, with the consent of a majority of its affected shareholders.","y":null,"e":"US CPA REG"}},{"n":5,"s":0.327,"o":{"i":"REGOX-reg_entities-065","t":"Under IRC §1368(e)(1)(C)(i), the balance of the accumulated adjustments account at the close of the taxable year, for purposes of distributions made during that year, is determined without regard to any net negative adjustment for that year.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-063","t":"Under IRC §1368(e)(1)(A), the accumulated adjustments account is adjusted for Federal taxes attributable to any taxable year in which the corporation was a C corporation.","y":null,"e":"US CPA REG"}},{"n":6,"s":0.458,"o":{"i":"REGOX-reg_entities-076","t":"Under IRC §1367(b)(2)(B), once a shareholder's debt basis has been reduced, a net increase for a subsequent taxable year is first applied to restore that reduction before it may increase the shareholder's stock basis.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-077","t":"Under IRC §1367(b)(2)(B), a net increase in basis items in a later year is applied to increase the shareholder's stock basis before restoring any prior reduction in debt basis.","y":null,"e":"US CPA REG"}},{"n":6,"s":0.3,"o":{"i":"REGOX-reg_entities-071","t":"Under IRC §1367(a)(2)(D), a shareholder's stock basis is decreased by any expense of the corporation not deductible in computing its taxable income and not properly chargeable to capital account.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-073","t":"Under IRC §1367(a)(2), the decrease in a shareholder's stock basis for a charitable contribution of property by the corporation equals the property's fair market value on the date of contribution.","y":null,"e":"US CPA REG"}},{"n":7,"s":0.323,"o":{"i":"REGOX-reg_entities-086","t":"Under IRC §707(c), a guaranteed payment to a partner for services, determined without regard to partnership income, is treated as a payment to a person who is not a partner for purposes of section 61(a) and, subject to section 263, section 162(a).","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-087","t":"Under IRC §707(c), a guaranteed payment is treated as a payment to a non-partner for all purposes of the Internal Revenue Code.","y":null,"e":"US CPA REG"}},{"n":8,"s":0.524,"o":{"i":"REGOX-reg_entities-090","t":"Under IRC §705(a)(1)(B), a partner's basis is increased by the partner's distributive share of partnership income exempt from tax.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-091","t":"Under IRC §705(a)(2), a partner's basis may be decreased below zero by the partner's distributive share of partnership losses.","y":null,"e":"US CPA REG"}},{"n":9,"s":0.366,"o":{"i":"REGOX-reg_entities-098","t":"Under IRC §7701(a)(3), the term 'corporation' includes associations, joint-stock companies, and insurance companies.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-102","t":"Under IRC §7701(a)(3), the term 'corporation' is defined to include partnerships and unincorporated joint ventures.","y":null,"e":"US CPA REG"}},{"n":9,"s":0.332,"o":{"i":"REGOX-reg_entities-097","t":"Under IRC §7701(a)(2), the term 'partnership' includes a syndicate, group, pool, joint venture, or other unincorporated organization through which a business, financial operation, or venture is carried on, provided it is not, within the meaning of the Code, a trust, estate, or corporation.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_entities-099","t":"Under IRC §7701(a)(2), the statutory term 'partnership' includes an unincorporated organization even if it is treated as a trust or estate under the Code.","y":null,"e":"US CPA REG"}}];
